<?php
session_start();
require_once "../config/database.php";

$products = [];
$result = $conn->query("SELECT id, product_name, category, price, addons, description, image_path FROM products WHERE status != 'Inactive' ORDER BY category, product_name");
if ($result) {
    while ($row = $result->fetch_assoc()) {
        $products[] = $row;
    }
}
$categories = [];
foreach ($products as $product) {
    if ($product["category"] !== "" && !in_array($product["category"], $categories, true)) {
        $categories[] = $product["category"];
    }
}
sort($categories);
function self_order_addons($value) {
    $decoded = json_decode((string) $value, true);
    if (!is_array($decoded)) return [];
    return array_values(array_filter(array_map(function ($addon) {
        if (is_string($addon)) return ["name" => trim($addon), "price" => 0];
        return ["name" => trim((string) ($addon["name"] ?? "")), "price" => max(0, (float) ($addon["price"] ?? 0))];
    }, $decoded), fn($addon) => $addon["name"] !== ""));
}
?>
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Self Ordering | Coffee Maker</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f8f4ef;color:#3d2013;font-family:Arial,Helvetica,sans-serif}.topbar{position:sticky;top:0;z-index:5;padding:13px 22px;background:linear-gradient(135deg,#5a2e1f,#7a4a2a);color:#fff;box-shadow:0 2px 15px #5a2e1f40}.topbar-inner{max-width:1120px;margin:auto;display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{display:flex;align-items:center;gap:10px}.brand-icon{width:38px;height:38px;display:grid;place-items:center;border-radius:10px;background:#d4a574;color:#5a2e1f;font-size:20px}.brand strong{display:block}.brand small{color:#d4a574}.top-actions{display:flex;gap:8px}.top-actions button{border:1px solid #ffffff40;border-radius:20px;padding:8px 13px;background:#ffffff1c;color:#fff;cursor:pointer;font-size:11px}.hero{max-width:1120px;margin:auto;padding:30px 22px 18px;text-align:center}.hero h1{margin:0;color:#5a2e1f;font-size:30px}.hero p{margin:7px 0;color:#b09585;font-size:13px}.filters{max-width:1120px;margin:auto;padding:0 22px 18px}.search{width:100%;height:40px;padding:0 14px;border:1px solid #dfd3cb;border-radius:20px;background:#fff;outline:none}.categories{display:flex;gap:8px;overflow:auto;padding-top:12px}.category{border:1px solid #e0d6ce;border-radius:20px;padding:7px 14px;background:#fff;color:#5a2e1f;white-space:nowrap;cursor:pointer;font-size:11px}.category.active{background:#5a2e1f;color:#fff}.menu{max-width:1120px;margin:auto;padding:0 22px 100px;display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:15px}.card{overflow:hidden;border-radius:12px;background:#fff;box-shadow:0 2px 8px #5a2e1f12;cursor:pointer}.card-image{height:125px;display:grid;place-items:center;background:#74473b;color:#fff;font-size:38px}.card-image img{width:100%;height:100%;object-fit:cover}.card-body{padding:13px}.card-body small{color:#b09585;font-size:10px}.card-body h2{margin:5px 0 9px;font-size:15px}.price{color:#7a4a2a;font-weight:800}.empty{text-align:center;grid-column:1/-1;color:#8e7e74;padding:45px}.splash{position:fixed;inset:0;z-index:20;display:grid;place-items:center;padding:18px;background:#eee2cd}.splash.hidden{display:none}.splash-card{width:min(100%,420px);padding:50px 25px;text-align:center;border:3px solid #fff;border-radius:13px;background:#eee2cd;box-shadow:0 2px 3px #5a2e1f44}.splash-logo{width:90px;height:90px;object-fit:contain}.splash-card h1{margin:20px 0 10px;font-size:25px;font-weight:400}.splash-card button{padding:11px 23px;border:1px solid #b8b8b8;border-radius:4px;background:#f5f5f5;color:#222;cursor:pointer}.modal{position:fixed;inset:0;z-index:10;display:none;place-items:center;padding:20px;background:#24150fcc}.modal.open{display:grid}.modal-card{width:min(100%,470px);max-height:90vh;overflow:auto;border-radius:14px;background:#fff;padding:22px}.modal-card h2{margin:0 0 8px}.option{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:8px 0;padding:10px;border:1px solid #e1d5ce;border-radius:8px;font-size:12px}.option input{accent-color:#7a4a2a}.modal-card input[type=text],.modal-card input[type=number]{width:100%;height:36px;border:1px solid #ded2cd;border-radius:6px;padding:8px}.modal-card textarea{width:100%;min-height:60px;border:1px solid #ded2cd;border-radius:6px;padding:8px}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}.modal-actions button{padding:10px 15px;border:0;border-radius:6px;cursor:pointer}.cancel{background:#eee;color:#4d3a32}.add{background:#7a4a2a;color:#fff}.cart{position:fixed;right:20px;bottom:20px;z-index:6;border:0;border-radius:25px;padding:13px 18px;background:#7a4a2a;color:#fff;box-shadow:0 4px 16px #5a2e1f55;cursor:pointer}.cart-count{display:inline-grid;place-items:center;width:20px;height:20px;margin-left:5px;border-radius:50%;background:#fff;color:#7a4a2a;font-size:10px}
</style>
</head>
<body>
<div class="splash" id="splash"><div class="splash-card"><img class="splash-logo" src="../assets/images/logo.png" alt="Coffee Maker"><h1>COFFEE MAKER</h1><button type="button" onclick="startOrdering()">TAP TO CONTINUE</button></div></div>
<header class="topbar"><div class="topbar-inner"><div class="brand"><div class="brand-icon">☕</div><div><strong>COFFEE MAKER</strong><small>Self-Ordering</small></div></div><div class="top-actions"><button type="button" onclick="resetOrdering()">Start Over</button><button type="button" onclick="showCart()">Cart <span id="topCount">0</span></button></div></div></header>
<section class="hero"><h1>Our Menu</h1><p>Tap a product to customize and order</p></section>
<section class="filters"><input class="search" id="search" type="search" placeholder="Search menu items..."><div class="categories"><button class="category active" data-category="all">All</button><?php foreach ($categories as $category): ?><button class="category" data-category="<?= htmlspecialchars($category) ?>"><?= htmlspecialchars($category) ?></button><?php endforeach; ?></div></section>
<main class="menu" id="menu"><?php if (!$products): ?><p class="empty">No active products found.</p><?php endif; ?><?php foreach ($products as $product): $addons=self_order_addons($product["addons"]); ?><article class="card" data-name="<?= htmlspecialchars(strtolower($product["product_name"])) ?>" data-category="<?= htmlspecialchars($product["category"]) ?>" data-id="<?= (int) $product["id"] ?>" data-product="<?= htmlspecialchars($product["product_name"]) ?>" data-price="<?= htmlspecialchars($product["price"]) ?>" data-addons='<?= htmlspecialchars(json_encode($addons), ENT_QUOTES) ?>'><div class="card-image"><?php if ($product["image_path"]): ?><img src="../<?= htmlspecialchars($product["image_path"]) ?>" alt="<?= htmlspecialchars($product["product_name"]) ?>"><?php else: ?>☕<?php endif; ?></div><div class="card-body"><small><?= htmlspecialchars($product["category"]) ?></small><h2><?= htmlspecialchars($product["product_name"]) ?></h2><div class="price">₱<?= number_format((float) $product["price"], 2) ?></div></div></article><?php endforeach; ?></main>
<button class="cart" type="button" onclick="showCart()">🛒 Cart <span class="cart-count" id="cartCount">0</span></button>
<div class="modal" id="productModal"><section class="modal-card"><h2 id="modalName"></h2><p id="modalPrice"></p><div id="addonList"></div><label>Quantity</label><input id="quantity" type="number" min="1" value="1"><label>Special requests</label><textarea id="notes" placeholder="e.g. Less ice..."></textarea><div class="modal-actions"><button class="cancel" type="button" onclick="closeProduct()">Cancel</button><button class="add" type="button" onclick="addToCart()">Add to Cart</button></div></section></div>
<div class="modal" id="cartModal"><section class="modal-card"><h2>Your Cart</h2><div id="cartItems"></div><div class="modal-actions"><button class="cancel" type="button" onclick="closeCart()">Continue</button><button class="add" type="button" onclick="placeOrder()">Place Order</button></div></section></div>
<script>
const cart=[];let selected=null;const money=v=>`₱${Number(v).toFixed(2)}`;const escapeText=v=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
function startOrdering(){document.getElementById('splash').classList.add('hidden')};function resetOrdering(){cart.length=0;updateCount();document.getElementById('splash').classList.remove('hidden')};function closeProduct(){document.getElementById('productModal').classList.remove('open')};function closeCart(){document.getElementById('cartModal').classList.remove('open')};
document.querySelectorAll('.card').forEach(card=>card.addEventListener('click',()=>{selected=card;document.getElementById('modalName').textContent=card.dataset.product;document.getElementById('modalPrice').textContent=money(card.dataset.price);document.getElementById('quantity').value=1;document.getElementById('notes').value='';let addons=[];try{addons=JSON.parse(card.dataset.addons||'[]')}catch(e){}document.getElementById('addonList').innerHTML=addons.map((a,i)=>`<label class="option"><span>${escapeText(a.name)} <small>+${money(a.price)}</small></span><input type="checkbox" data-name="${escapeText(a.name)}" data-price="${a.price}"></label>`).join('');document.getElementById('productModal').classList.add('open')}));
function addToCart(){const quantity=Math.max(1,Number(document.getElementById('quantity').value)||1);const addons=[...document.querySelectorAll('#addonList input:checked')].map(i=>({name:i.dataset.name,price:Number(i.dataset.price)}));const price=Number(selected.dataset.price)+addons.reduce((s,a)=>s+a.price,0);cart.push({productId:Number(selected.dataset.id),name:selected.dataset.product,price,quantity,addons,notes:document.getElementById('notes').value.trim()});updateCount();closeProduct()};function updateCount(){const n=cart.reduce((s,i)=>s+i.quantity,0);document.getElementById('cartCount').textContent=n;document.getElementById('topCount').textContent=n};
function showCart(){document.getElementById('cartItems').innerHTML=cart.length?cart.map((i,n)=>`<div class="option"><span>${i.quantity}x ${escapeText(i.name)}<br><small>${i.addons.length?'ADD-ONS: '+escapeText(i.addons.map(a=>a.name).join(', ')):'No add-ons'}</small></span><strong>${money(i.price*i.quantity)}</strong></div>`).join(''):'<p>Your cart is empty.</p>';document.getElementById('cartModal').classList.add('open')};
async function placeOrder(){if(!cart.length)return;const items=cart.map(i=>({productId:i.productId,quantity:i.quantity,unitPrice:i.price,size:'Regular',addons:i.addons.map(a=>a.name),notes:i.notes}));const data=new FormData();data.append('action','create_order');data.append('order',JSON.stringify({items}));const response=await fetch('pos.php?mode=self-order',{method:'POST',body:data});const result=await response.json();if(result.success){alert('Order placed: '+result.order_number);cart.length=0;updateCount();closeCart()}else alert(result.message||'Unable to place order')};
document.getElementById('search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.card').forEach(c=>c.hidden=!c.dataset.name.includes(q))});document.querySelectorAll('.category').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.category').forEach(x=>x.classList.remove('active'));b.classList.add('active');const cat=b.dataset.category;document.querySelectorAll('.card').forEach(c=>c.hidden=cat!=='all'&&c.dataset.category!==cat)}));
</script>
</body>
</html>
